begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create function pg_temp.fixture(external boolean default false,caps text[] default array['calendar','email']) returns jsonb language plpgsql as $$
declare p uuid:=gen_random_uuid();actor uuid;request uuid:=gen_random_uuid();invite uuid;ctx jsonb;
begin
 actor:=gen_random_uuid();insert into auth.users(id,email)values(actor,actor::text||'@fixture.invalid');update public.profiles set org_id='22222222-2222-2222-2222-222222222222' where id=actor;
 insert into public.properties(id,name,org_id,settings) values(p,'Authorization SQL fixture','22222222-2222-2222-2222-222222222222','{"timezone":"UTC"}');
 insert into public.lumaleasing_config(property_id,api_key,timezone)values(p,'fixture-'||p::text,'UTC');
 if external then
  invite:=gen_random_uuid();insert into public.integration_auth_invites(id,property_id,provider,requested_capabilities,token_hash,expires_at,created_by_profile_id) values(invite,p,'google',caps,encode(sha256(convert_to(invite::text,'UTF8')),'hex'),clock_timestamp()+interval '1 hour',actor);
 end if;
 ctx:=jsonb_build_object('propertyId',p,'profileId',case when external then null else actor end,'provider','google','capabilities',caps,'authSource',case when external then 'external_invite' else 'dashboard' end,'inviteId',invite,'tokenHash',case when external then encode(sha256(convert_to(invite::text,'UTF8')),'hex') else null end,'redirectUri','https://app.invalid/callback','requestedScopes',array['https://www.googleapis.com/auth/calendar','https://www.googleapis.com/auth/gmail.modify']);
 perform public.begin_integration_authorization(request,ctx);
 return jsonb_build_object('p',p,'actor',actor,'id',request,'invite',invite,'context',ctx);
end$$;
create function pg_temp.claim(f jsonb) returns jsonb language sql as $$select public.claim_integration_authorization((f->>'id')::uuid,f->'context')$$;
create function pg_temp.grant() returns jsonb language sql as $$select jsonb_build_object('accessToken','fixture-access','refreshToken','fixture-refresh','expiresAt',now()+interval '1 hour','accountEmail','fixture@example.invalid','subject','provider-subject','timezone','UTC','scopes',array['https://www.googleapis.com/auth/calendar','https://www.googleapis.com/auth/gmail.modify'],'scopeEvidence','provider_response')$$;
create function pg_temp.finish(f jsonb,g jsonb default pg_temp.grant()) returns jsonb language sql as $$select public.finish_integration_authorization((f->>'id')::uuid,f->'context',g)$$;
do $$declare f jsonb;r jsonb;g jsonb:=pg_temp.grant();c uuid;m uuid;d uuid;second uuid;
begin
 f:=pg_temp.fixture(true);
 perform pg_temp.check(pg_temp.claim(f)->>'state'='claimed','first callback claims exchange');
 perform pg_temp.check(pg_temp.claim(f)->>'state'='authorization_unconfirmed','same callback cannot exchange twice');
 r:=pg_temp.finish(f,g);perform pg_temp.check(r->>'state'='saved','combined authorization saved');c:=(r->>'calendarId')::uuid;m:=(r->>'emailConfigId')::uuid;
 perform pg_temp.check((select access_token='fixture-access' and provider_subject='provider-subject' from public.agent_calendars where id=c),'calendar credential and identity stored');
 perform pg_temp.check((select access_token='fixture-access' and provider_subject='provider-subject' from public.email_configurations where id=m),'email credential and identity stored');
 perform pg_temp.check((select email_enabled and email_configuration_id=m from public.lumaleasing_config where property_id=(f->>'p')::uuid),'widget points to saved email');
 perform pg_temp.check((select consumed_at is not null and consumed_calendar_id=c and consumed_email_configuration_id=m from public.integration_auth_invites where id=(f->>'invite')::uuid),'invitation consumed with both saved IDs');
 perform pg_temp.check((select action='integration.authorization.completed' and request->>'authorizer'='external_account' and not training_eligible and request::text not like '%fixture-access%' and after_state::text not like '%fixture-refresh%' from public.shared_action_events where id=(f->>'id')::uuid),'external invitation event identifies authorizer and excludes secrets');
 perform pg_temp.check(pg_temp.claim(f)->>'state'='replayed','completed callback recovers before provider call');
 perform pg_temp.check(pg_temp.finish(f,g)->>'state'='replayed','identical finalization recovers');
 perform pg_temp.check(pg_temp.finish(f,g||'{"subject":"other"}')->>'state'='request_conflict','different grant cannot reuse saved request');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where id=(f->>'id')::uuid),'recovery retains one action');
 perform pg_temp.check(public.begin_integration_authorization(gen_random_uuid(),f->'context')->>'state'='invite_unavailable','consumed invitation cannot start another attempt');
 perform public.disconnect_recorded_calendar((f->>'p')::uuid,(f->>'actor')::uuid,gen_random_uuid());
 perform pg_temp.check(pg_temp.claim(f)->>'state'='connection_changed','old successful callback cannot claim current success after removal');
 f:=pg_temp.fixture(true);perform pg_temp.claim(f);update public.integration_auth_invites set revoked_at=now() where id=(f->>'invite')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='invite_unavailable','revoked after claim cannot finalize');
 perform pg_temp.check(not exists(select 1 from public.agent_calendars where property_id=(f->>'p')::uuid),'revoked invitation creates no calendar');
 perform pg_temp.check(not exists(select 1 from public.email_configurations where property_id=(f->>'p')::uuid),'revoked invitation creates no email');
 f:=pg_temp.fixture(true);perform pg_temp.claim(f);update public.integration_auth_invites set expires_at=now()-interval '1 second' where id=(f->>'invite')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='invite_unavailable','expired during provider exchange cannot finalize');
 f:=pg_temp.fixture(true);perform pg_temp.claim(f);update public.integration_auth_invites set requested_capabilities=array['email'] where id=(f->>'invite')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='invite_unavailable','changed invitation capabilities cannot finalize');
 f:=pg_temp.fixture();perform pg_temp.claim(f);perform public.disconnect_recorded_calendar((f->>'p')::uuid,(f->>'actor')::uuid,gen_random_uuid());
 perform pg_temp.check(pg_temp.finish(f)->>'state'='connection_changed','calendar removal cancels even an initially empty connection attempt');
 f:=pg_temp.fixture();perform pg_temp.claim(f);perform public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,gen_random_uuid());
 perform pg_temp.check(pg_temp.finish(f)->>'state'='connection_changed','email removal cancels initially empty combined attempt');
 f:=pg_temp.fixture();second:=gen_random_uuid();perform public.begin_integration_authorization(second,f->'context');perform pg_temp.claim(f);perform public.claim_integration_authorization(second,f->'context');perform pg_temp.finish(f);
 perform pg_temp.check(public.finish_integration_authorization(second,f->'context',g)->>'state'='connection_changed','competing callback cannot overwrite first commit');
 f:=pg_temp.fixture();perform pg_temp.claim(f);perform pg_temp.finish(f);
 second:=gen_random_uuid();perform public.begin_integration_authorization(second,f->'context');perform public.claim_integration_authorization(second,f->'context');
 perform pg_temp.check(public.finish_integration_authorization(second,f->'context',g||'{"subject":"replacement","accountEmail":"other@example.invalid"}')->>'state'='account_replacement_required','different account held before both writes');
 perform pg_temp.check((select provider_subject='provider-subject' from public.agent_calendars where property_id=(f->>'p')::uuid),'held account change preserves calendar identity');
 perform pg_temp.check((select account_email='fixture@example.invalid' from public.email_configurations where property_id=(f->>'p')::uuid),'held account change preserves email identity');
 second:=gen_random_uuid();perform public.begin_integration_authorization(second,f->'context');perform public.claim_integration_authorization(second,f->'context');
 perform pg_temp.check(public.finish_integration_authorization(second,f->'context',g)->>'state'='saved','same verified account reconnects');
 f:=pg_temp.fixture();perform pg_temp.claim(f);update public.profiles set org_id=null where id=(f->>'actor')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='forbidden','membership rechecked at final save');
 f:=pg_temp.fixture();perform pg_temp.claim(f);update public.integration_authorizations set expires_at=now()-interval '1 second' where id=(f->>'id')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='expired_state','expired authorization cannot save');
 f:=pg_temp.fixture();perform pg_temp.claim(f);delete from public.lumaleasing_config where property_id=(f->>'p')::uuid;
 perform pg_temp.check(pg_temp.finish(f)->>'state'='connection_changed','changed widget binding holds entire combined save');
 f:=pg_temp.fixture();perform pg_temp.check(public.claim_integration_authorization((f->>'id')::uuid,(f->'context')||'{"provider":"microsoft"}')->>'state'='request_conflict','altered callback context rejected');
 perform pg_temp.check(not has_table_privilege('authenticated','public.integration_authorizations','select'),'authorization ledger private');
 perform pg_temp.check(not has_table_privilege('authenticated','public.email_configurations','select'),'email tokens not browser readable');
 perform pg_temp.check(not has_table_privilege('authenticated','public.integration_auth_invites','update'),'browser cannot alter invitation authority');
 perform pg_temp.check(not has_function_privilege('authenticated','public.finish_integration_authorization(uuid,jsonb,jsonb)','execute'),'finalization private');
end$$;
create function pg_temp.reject_authorization_record() returns trigger language plpgsql as $$begin if new.action='integration.authorization.completed' then raise exception 'fixture recording failure';end if;return new;end$$;
create trigger fixture_reject_authorization before insert on public.shared_action_events for each row execute function pg_temp.reject_authorization_record();
do $$declare f jsonb;r jsonb;failed boolean:=false;begin
 f:=pg_temp.fixture(true);perform pg_temp.claim(f);
 begin perform pg_temp.finish(f);exception when others then failed:=true;end;
 perform pg_temp.check(failed,'recording failure surfaced');
 perform pg_temp.check(not exists(select 1 from public.agent_calendars where property_id=(f->>'p')::uuid),'recording failure rolls back calendar');
 perform pg_temp.check(not exists(select 1 from public.email_configurations where property_id=(f->>'p')::uuid),'recording failure rolls back email');
 perform pg_temp.check((select consumed_at is null from public.integration_auth_invites where id=(f->>'invite')::uuid),'recording failure restores invitation');
 perform pg_temp.check((select not coalesce(email_enabled,false) and email_configuration_id is null from public.lumaleasing_config where property_id=(f->>'p')::uuid),'recording failure restores widget');
 perform pg_temp.check((select status='exchanging' from public.integration_authorizations where id=(f->>'id')::uuid),'failed save retains claim for identical retry');
end$$;
drop trigger fixture_reject_authorization on public.shared_action_events;

do $$declare f jsonb;r jsonb;d uuid;begin
 f:=pg_temp.fixture();perform pg_temp.claim(f);perform pg_temp.finish(f);d:=gen_random_uuid();
 r:=public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,d);
 perform pg_temp.check(r->>'state'='applied' and r->>'disconnected'='1','email removal acknowledged');
 perform pg_temp.check((select access_token is null and refresh_token is null and not sync_enabled and not auto_reply_enabled from public.email_configurations where property_id=(f->>'p')::uuid),'email removal clears credentials and automation');
 perform pg_temp.check((select not email_enabled and email_configuration_id is null from public.lumaleasing_config where property_id=(f->>'p')::uuid),'email removal and widget binding commit together');
 perform pg_temp.check(public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,d)->>'state'='replayed','email removal retries one decision');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where id=d),'one email disconnection record');
end$$;
create function pg_temp.reject_email_record() returns trigger language plpgsql as $$begin if new.action='email.disconnected' then raise exception 'fixture email history failure';end if;return new;end$$;
create trigger fixture_reject_email before insert on public.shared_action_events for each row execute function pg_temp.reject_email_record();
do $$declare f jsonb;failed boolean:=false;begin
 f:=pg_temp.fixture();perform pg_temp.claim(f);perform pg_temp.finish(f);
 begin perform public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,gen_random_uuid());exception when others then failed:=true;end;
 perform pg_temp.check(failed,'email recording failure surfaced');
 perform pg_temp.check((select access_token='fixture-access' and sync_enabled from public.email_configurations where property_id=(f->>'p')::uuid),'failed recording restores email credentials');
 perform pg_temp.check((select email_enabled and email_configuration_id is not null from public.lumaleasing_config where property_id=(f->>'p')::uuid),'failed recording restores widget binding');
end$$;
drop trigger fixture_reject_email on public.shared_action_events;
select count(*) as passed from checks;
rollback;
